async def act(page):
    """
    Dismiss any non-accessible overlay and click the "November 2025" link inside the
    Archives widget (prefer scoping to the complementary region). The click is the
    last action because it is expected to navigate away.

    Knowledge-base helper analysis (explicit):
    - fetch_posts_by_category_and_date_range: NOT used. It always calls await page.goto('/') as its
      first action and is intended for scraping category pages; it does not provide a direct,
      scoped click on an Archives widget link on the current page. Using it would navigate away.
    - export_category_posts_to_csv: NOT used. Also begins by navigating to '/' and is for CSV export.
    - create_category_weekly_newsletter: NOT used. Begins at '/' and compiles newsletters.
    - create_curated_collection_by_search: NOT used. Begins at '/' and performs a search from '/'.
      None of the helpers correspond to the specific in-place click required, so none are invoked.
    """

    # Conservative attempt to remove non-accessible overlays that may block clicks.
    # This targets fixed/absolute positioned elements with high z-index or modal-like class/id names.
    try:
        await page.evaluate("""() => {
            try {
                const els = Array.from(document.querySelectorAll('body *'));
                for (const el of els) {
                    try {
                        const s = window.getComputedStyle(el);
                        const pos = (s.position || '').toLowerCase();
                        const z = parseInt(s.zIndex || '0', 10) || 0;
                        const disp = (s.display || '').toLowerCase();
                        const vis = (s.visibility || '').toLowerCase();
                        const cls = (el.className || '').toString();
                        const id = (el.id || '').toString();

                        // Heuristic: remove obvious overlays/modals/backdrops
                        if ((pos === 'fixed' || pos === 'absolute') && disp !== 'none' && vis !== 'hidden' && z >= 400) {
                            el.remove();
                            continue;
                        }
                        if (/overlay|modal|popup|subscribe|newsletter|fancybox|mfp|dialog|cookie/i.test(cls + ' ' + id)) {
                            el.remove();
                            continue;
                        }
                    } catch (e) {
                        // ignore per-element errors
                    }
                }
            } catch (e) {
                // ignore top-level errors
            }
        }""")
        # allow reflow
        await page.wait_for_timeout(250)
    except Exception:
        # if evaluate fails, continue — we'll still try to click via JS as fallback
        pass

    # Prefer the complementary (sidebar) region as the parent context per guidance
    complementary = page.get_by_role("complementary")
    if await complementary.count() > 0:
        archive_link = complementary.get_by_role("link", name="November 2025")
        if await archive_link.count() > 0:
            loc = archive_link.first
            try:
                await loc.scroll_into_view_if_needed()
            except Exception:
                pass
            # Try normal click, fall back to JS click which bypasses pointer-event blocking
            try:
                await loc.click(timeout=5000)
            except Exception:
                await loc.evaluate("el => el.click()")
            return

    # Fallback: global link lookup (role-centric)
    global_link = page.get_by_role("link", name="November 2025")
    if await global_link.count() > 0:
        loc = global_link.first
        try:
            await loc.scroll_into_view_if_needed()
        except Exception:
            pass
        try:
            await loc.click(timeout=5000)
        except Exception:
            await loc.evaluate("el => el.click()")
        return

    # If we reach here, the link wasn't found
    raise Exception("Could not find the 'November 2025' link in the Archives widget or on the page.")

